    def all_interventions(
        self, service_name: str
    ) -> t.AsyncIterator[models.DedicatedServerIntervention]:
        """all_interventions iterates over GET /v1/dedicated/server/{serviceName}/intervention (List past interventions).

        It lists the IDs with list_interventions, then gets each object with get_intervention,
        only when the loop reaches it. An object deleted in the meantime is skipped. Any other
        error is raised and stops the loop. Use it with ``async for``.

        Args:
            service_name: The internal name of your dedicated server

        The two calls require the IAM action dedicatedServer:apiovh:intervention/get.
        """
        return self._each(
            lambda: self.list_interventions(
                service_name,
            ),
            lambda listed_id: self.get_intervention(service_name, listed_id),
        )

